<?php require __DIR__.'/config/bootstrap.php'; $page_title='Sectors · '.site_setting('company_name'); require __DIR__.'/includes/header.php'; $items=db_rows('SELECT * FROM sectors WHERE active=1 ORDER BY sort_order,id'); ?><section class="page-hero"><div class="container"><span class="eyebrow">Sectors</span><h1>Built for different project environments.</h1><p>Sectors are highlighted on the homepage and footer so the main menu stays focused on what visitors need most.</p></div></section><section class="section"><div class="container"><div class="sectors-grid"><?php if(!$items): ?><p class="empty-state">No sectors are published yet. Add them in <strong>Admin &rarr; Sectors</strong>.</p><?php endif; ?><?php foreach($items as $s): ?><article id="s<?=e($s['id'])?>" class="sector-card"><i class="<?=e($s['icon'])?>"></i><h3><?=e($s['title'])?></h3><p><?=e($s['description'])?></p></article><?php endforeach;?></div></div></section><?php require __DIR__.'/includes/footer.php'; ?>